```js
export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	if (ttlMs !== undefined && !(Number.isInteger(ttlMs) && ttlMs >= 0)) {
		throw new RangeError("ttlMs must be an integer >= 0");
	}
	const ttl = ttlMs === undefined ? 0 : ttlMs;
	const cache = new Map(); // key -> { stamp, response }
	const inFlight = new Map(); // key -> Promise
	const stats = { hits: 0, misses: 0, fetches: 0 };

	const stripFragment = (u) => u.slice(0, u.indexOf("#") === -1 ? u.length : u.indexOf("#"));

	const doFetch = (key) => {
		stats.fetches += 1;
		return Promise.resolve()
			.then(() => fetchImpl(key))
			.then(async (response) => {
				const { status, body } = response;
				const result = { status, body };
				if (Number.isInteger(status) && status >= 200 && status <= 299) {
					const stamp = now();
					if (ttl > 0) cache.set(key, { stamp, response: result });
				}
				return result;
			});
	};
```

