export function createClient({ fetchImpl, now = Date.now, ttlMs } = {}) {
	if (typeof fetchImpl !== "function") throw new TypeError("fetchImpl must be a function");
	if (ttlMs !== undefined && (!Number.isInteger(ttlMs) || ttlMs < 0)) throw new RangeError("ttlMs must be an integer of 0 or more");

	const ttl = ttlMs ?? 0;
	const cache = new Map();
	const inFlight = new Map();
	const counts = { hits: 0, misses: 0, fetches: 0 };

	const keyOf = (url) => {
		const i = url.indexOf("#");
		return i === -1 ? url : url.slice(0, i);
	};

	const perform = (key) => {
		counts.fetches += 1;
		return Promise.resolve()
			.then(() => fetchImpl(key))
			.then((response) => {
				const result = { status: response.status, body: response.body };
				if (ttl > 0 && response.status >= 200 && response.status <= 299) {
					const stamp = now();
					cache.set(key, { stamp, response: structuredClone(result) });
				}
				return result;
			});
	};

	const get = async (url, opts) => {
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		const key = keyOf(url);
		const fresh = Boolean(opts && opts.fresh);

		if (!fresh) {
			const entry = cache.get(key);
			if (entry !== undefined) {
				if (now() - entry.stamp < ttl) {
					counts.hits += 1;
					return structuredClone(entry.response);
				}
				cache.delete(key);
			}
		}
		counts.misses += 1;

		let promise;
		if (fresh) {
			promise = perform(key);
		} else {
			promise = inFlight.get(key);
			if (!promise) {
				promise = perform(key);
				const tracked = promise.finally(() => {
					if (inFlight.get(key) === tracked) inFlight.delete(key);
				});
				inFlight.set(key, tracked);
				promise = tracked;
			}
		}
		return structuredClone(await promise);
	};

	const clear = (url) => {
		if (url === undefined) return cache.clear();
		if (typeof url !== "string" || url === "") throw new TypeError("url must be a non-empty string");
		cache.delete(keyOf(url));
	};

	const stats = () => ({ hits: counts.hits, misses: counts.misses, fetches: counts.fetches });

	return { get, clear, stats };
}
```

