	assert.equal(m.calls.length, 2); // not cached
	assert.deepEqual(m.c.stats(), { hits: 0, misses: 2, fetches: 2 });

	const m2 = mk({ ttlMs: 1000, response: { status: 200, body: "ok" } });
	await m2.c.get("u");
	const err = new Error("boom");
	m2.resolvers.length = 0;
	// switch fetch to rejecting via a fresh manual client
	let rej;
	const c3 = createClient({
		fetchImpl: () => new Promise((_, r) => (rej = r)),
		now: () => 0, ttlMs: 1000,
	});
	rej(err);
	const p3 = c3.get("u");
	await assert.rejects(p3, (e) => e === err);
	assert.deepEqual(c3.stats(), { hits: 0, misses: 1, fetches: 1 });
}

// R4: in-flight dedupe (same url, fragments ignored), works with ttl 0
{
	const m = mk({ ttlMs: 0, manual: true });
	const p1 = m.c.get("http://x/a#1");
	const p2 = m.c.get("http://x/a");
	const p3 = m.c.get("http://x/a#2");
	assert.equal(m.calls.length, 1);
	m.resolvers[0][0]({ status: 200, body: "shared" });
	assert.deepEqual(await p1, { status: 200, body: "shared" });
	assert.deepEqual(await p2, { status: 200, body: "shared" });
	assert.deepEqual(await p3, { status: 200, body: "shared" });
	assert.deepEqual(m.c.stats(), { hits: 0, misses: 3, fetches: 1 });
	// after completion, next call starts afresh
	m.setNow(5);
	await m.c.get("http://x/a");
	assert.equal(m.calls.length, 2);
}

// R4: rejection shared by waiters, then next call refetches
{
	let rej;
	const calls = [];
	const c = createClient({
		fetchImpl: () => { calls.push(1); return new Promise((_, r) => (rej = r)); },
		now: () => 0, ttlMs: 1000,
	});
	const e1 = new Error("e1");
	const p1 = c.get("u");
	const p2 = c.get("u");
	assert.equal(calls.length, 1);
	rej(e1);
	await assert.rejects(p1, (e) => e === e1);
	await assert.rejects(p2, (e) => e === e1);
	assert.equal(c.calls.length, 1);
}

// R5: fresh always fetches, never waits, replaces entry on 2xx only
{
	const m = mk({ ttlMs: 1000, manual: true });
	const p1 = m.c.get("u"); // in flight
	const pf = m.c.get("u", { fresh: true }); // must NOT wait for p1; own fetch
	assert.equal(m.calls.length, 2);
	m.resolvers[1][0]({ status: 200, body: "fresh" });
	const rf = await pf;
	assert.deepEqual(rf, { status: 200, body: "fresh" });
	m.resolvers[0][0]({ status: 200, body: "old" });
	await p1;
	// now cache should hold "fresh" (fresh completed 2nd, but p1 completed later!)
	// order: p1 resolves after fresh; p1's 2xx would overwrite. Verify:
	const r2 = await m.c.get("u");
	assert.equal(r2.body, "old"); // last to resolve wins the entry
	// fresh non-2xx leaves entry alone
	const m2 = mk({ ttlMs: 1000, response: { status: 200, body: "keep" } });
	await m2.c.get("u");
	const m2b = mk; // noop
	// use manual to control status per call
	let n = 0;
	const calls2 = [];
	const c2 = createClient({
		fetchImpl: async (url) => { calls2.push(url); n++; return n === 1 ? { status: 200, body: "keep" } : { status: 503, body: "down" }; },
		now: () => 0, ttlMs: 1000,
	});
	const r1 = await c2.get("u");
	assert.equal(r1.body, "keep");
	const r2 = await c2.get("u", { fresh: true });
	assert.equal(r2.body, "down");
	const r3 = await c2.get("u");
	assert.equal(r3.body, "keep"); // entry left alone after non-2xx fresh
	assert.deepEqual(c2.stats(), { hits: 1, misses: 2, fetches: 3 });
	// fresh with ttl 0: nothing stored
	const c3 = createClient({ fetchImpl: async () => ({ status: 200, body: 1 }), now: () => 0, ttlMs: 0 });
	await c3.get("u", { fresh: true }); await c3.get("u", { fresh: true });
	assert.equal(c3.stats().fetches, 2);
}

// R6: clear
{
	const m = mk({ ttlMs: 1000, response: { status: 200, body: 1 } });
	await m.c.get("a"); await m.c.get("b");
	m.c.clear("a#frag");
	m.setNow(1);
	await m.c.get("a"); // refetched
	await m.c.get("b"); // still cached
	assert.deepEqual(m.c.stats(), { hits: 1, misses: 3, fetches: 3 });
	m.c.clear();
	m.setNow(2);
	await m.c.get("b");
	assert.equal(m.calls.length, 4);
	// clear doesn't affect in-flight
	const m2 = mk({ ttlMs: 1000, manual: true });
	const p1 = m2.c.get("u");
	m2.c.clear();
	m2.resolvers[0][0]({ status: 200, body: "x" });
	assert.deepEqual(await p1, { status: 200, body: "x" });
}

// R7: deep copy isolation, including shared in-flight callers
{
	const m = mk({ ttlMs: 1000, manual: true });
	const p1 = m.c.get("u");
	const p2 = m.c.get("u");
	m.resolvers[0][0]({ status: 200, body: { deep: [{ x: 1 }] } });
	const r1 = await p1, r2 = await p2, r3 = await m.c.get("u"); // r3 from cache
	r1.body.deep[0].x = 99; r1.status = 999;
	r2.body.deep[0].x = 88;
	assert.equal(r3.body.deep[0].x, 1);
	assert.equal(r3.status, 200);
	const r4 = await m.c.get("u");
	assert.equal(r4.body.deep[0].x, 1);
	assert.notEqual(r1.body, r2.body);
	assert.notEqual(r1.body.deep, r2.body.deep);
}

// R7: bad url rejects as promise
{
	const m = mk({ response: { status: 200, body: 1 } });
	await assert.rejects(Promise.resolve().then(() => m.c.get("")), TypeError);
	await assert.rejects(Promise.resolve().then(() => m.c.get(42)), TypeError);
	await assert.rejects(Promise.resolve().then(() => m.c.get(null)), TypeError);
	assert.deepEqual(m.c.stats(), { hits: 0, misses: 0, fetches: 0 }); // failed URL checks not counted
}

