// R2: stamp read right after fetchImpl resolves (fetch takes time)
{
	const calls = [];
	let resolveFetch;
	const pending = new Promise((res) => (resolveFetch = res));
	const c = createClient({
		fetchImpl: () => { calls.push(1); return pending; },
		now: () => t,
		ttlMs: 100,
	});
	t = 0;
	const p1 = c.get("u"); // fetch starts at t=0, still pending
	t = 500;
	resolveFetch({ status: 200, body: "x" }); // resolves at t=500 -> stamp must be 500
	await p1;
	t = 550; await c.get("u"); // 550-500 = 50 < 100 -> hit (would refetch if stamp were 0)
	assert.equal(calls.length, 1);
	t = 600; await c.get("u"); // 600-500 = 100 >= 100 -> expired -> refetch
	assert.equal(calls.length, 2);
	assert.equal(c.stats().hits, 1);
}

