	assert.equal(m.calls.length, 1);
	assert.deepEqual(m.c.stats(), { hits: 1, misses: 1, fetches: 1 });
	await m.c.get("u", {});
	assert.equal(m.calls.length, 1);
}

// R5: two concurrent fresh calls each call fetchImpl; fresh result is deep-copied
{
	const m = mk({ ttlMs: 1000, manual: true });
	const f1 = m.c.get("u", { fresh: true });
	const f2 = m.c.get("u", { fresh: true });
	assert.equal(m.calls.length, 2);
	m.resolvers[0][0]({ status: 200, body: { a: 1 } });
	m.resolvers[1][0]({ status: 200, body: { a: 2 } });
	const r1 = await f1, r2 = await f2;
	assert.deepEqual(r1.body, { a: 1 });
	assert.deepEqual(r2.body, { a: 2 });
	r2.body.a = 42; // must not leak into stored entry (last write = {a:2})
	const r3 = await m.c.get("u");
	assert.equal(r3.body.a, 2);
}

// R4/R5 interplay: fresh call ignores in-flight, in-flight waiters unaffected
{
	const m = mk({ ttlMs: 1000, manual: true });
	const n1 = m.c.get("u");
	const n2 = m.c.get("u");
	assert.equal(m.calls.length, 1);
	const f = m.c.get("u", { fresh: true }); // independent 2nd fetch
	assert.equal(m.calls.length, 2);
	m.resolvers[0][0]({ status: 200, body: "n" });
	m.resolvers[1][0]({ status: 404, body: "nf" }); // fresh non-2xx: leaves entry alone
	assert.deepEqual(await n1, { status: 200, body: "n" });
	assert.deepEqual(await n2, { status: 200, body: "n" });
	assert.deepEqual(await f, { status: 404, body: "nf" });
	const after = await m.c.get("u"); // entry from normal fetch still valid
	assert.equal(after.body, "n");
	assert.equal(m.c.stats().fetches, 2);
}

