{
	const m = mk({ ttlMs: 1000, response: { status: 200, body: 1 } });
	m.c.clear("nope");
	m.c.clear("u#f");
	assert.throws(() => m.c.clear(123), TypeError);
	assert.throws(() => m.c.clear(""), TypeError);
	m.c.clear(); // no-arg still fine after all of that
	assert.deepEqual(m.c.stats(), { hits: 0, misses: 0, fetches: 0 });
